	private void assertExperimentalQueryOptimizationRoundTrip(boolean legacy) {
		var implNode = bnode();
		var setting = legacy ? BaseSailSchema.EXPERIMENTAL_QUERY_OPTIMIZATIONS
				: CONFIG.Sail.experimentalQueryOptimizations;

		var defaultConfig = new BaseSailConfig("stub") {
		};
		defaultConfig.parse(new LinkedHashModel(), implNode);
		assertThat(defaultConfig.isExperimentalQueryOptimizations()).isFalse();
		var defaultExport = new LinkedHashModel();
		var defaultExportNode = defaultConfig.export(defaultExport);
		assertThat(defaultExport.contains(defaultExportNode, setting, null)).isFalse();

		var enabledConfig = new BaseSailConfig("stub") {
		};
		var enabledModel = new ModelBuilder().add(implNode, setting, literal(true)).build();
		enabledConfig.parse(enabledModel, implNode);
		assertThat(enabledConfig.isExperimentalQueryOptimizations()).isTrue();
		var enabledExport = new LinkedHashModel();
		var enabledExportNode = enabledConfig.export(enabledExport);
		assertThat(enabledExport.contains(enabledExportNode, setting, literal(true))).isTrue();

		var disabledConfig = new BaseSailConfig("stub") {
		};
		var disabledModel = new ModelBuilder().add(implNode, setting, literal(false)).build();
		disabledConfig.parse(disabledModel, implNode);
		assertThat(disabledConfig.isExperimentalQueryOptimizations()).isFalse();
		var disabledExport = new LinkedHashModel();
		var disabledExportNode = disabledConfig.export(disabledExport);
		assertThat(disabledExport.contains(disabledExportNode, setting, null)).isFalse();
	}
